    "A": "Faux. La synostose coronale donne la plagiocéphalie ou la brachycéphalie.",
    "B": "Vrai (Corrigé officiel : B). La fermeture prématurée de la suture sagittale bloque l'expansion transversale et provoque la scaphocéphalie.",
