    "B": "Proposition exacte. Processus neurodégénératif à plaques amyloïdes et dégénérescence neurofibrillaire Tau.",
    "C": "Réponse fausse (Corrigé officiel : C). Le diagnostic de démence exige une évolution chronique depuis plus de 6 mois.",
    "_synthese": "Maladie d'Alzheimer : Démence neurodégénérative la plus fréquente (A, B) nécessitant un critère chronologique d'au moins 6 mois (C faux).",
    "_remarque": "Une altération cognitive d'installation rapide en quelques semaines à 2 mois doit faire rechercher une encéphalite auto-immune ou une maladie à prions (Creutzfeldt-Jakob)."
