    "D": "Proposition exacte. Les symptômes non moteurs (dysautonomie, neuropsychiatrie, troubles digestifs et sensitifs) sont fréquents et précoces.",
    "_synthese": "Traitement de Parkinson : Agonistes dopaminergiques avant 65 ans (B faux : pas L-dopa d'emblée) ; L-dopa de choix après 65-70 ans.",
