    "_synthese": "Syndrome myogène : Déficit proximal des ceintures (A, B), marche dandinante (C), pseudohypertrophie (D). Marche pseudo-ébrieuse = cérébelleuse (E faux).",
    "_remarque": "Dans le syndrome myogène pur, les réflexes ostéo-tendineux sont longtemps conservés et il n'y a aucun trouble sensitif."
