    "_remarque": "📌 Note aux étudiants de la Faculté de Médecine de Mostaganem : Cette question est issue des examens officiels de la Faculté de Médecine d'Alger (Session P1 2025-2026). Elle est intégrée dans votre programme de 4ème année pour vous offrir un entraînement transversal exhaustif et optimiser votre réussite aux EMD. • L'oxygénothérapie à fort débit (12-15 L/min au masque) est le traitement spécifique de crise de l'algie vasculaire de la face."
