    "_synthese": "La crise généralisée tonico-clonique (grand mal) débute d'emblée par une perte de connaissance soudaine et brutale entraînant la chute, avant le déroulement successif des trois phases (tonique, clonique et résolutive stertoreuse).",
    "_remarque": "Clé du PDF conservée ; question à la formulation ambiguë. 📌 Note aux étudiants de la Faculté de Médecine de Mostaganem : Cette question est issue des examens officiels de la Faculté de Médecine d'Alger (Session P1 2025-2026). Elle est intégrée dans votre programme de 4ème année pour vous offrir un entraînement transversal exhaustif et optimiser votre réussite aux EMD. • La morsure du bord latéral de la langue est un signe hautement spécifique d'une crise comitiale généralisée (par opposition aux syncopes ou crises psychogènes)."
